/**
 * Checkout pipeline per the README. Discounts, coupon, and tax are each
 * rounded half-up (half away from zero) once, at the stage where they occur —
 * the coupon is a single rounding over the whole discounted subtotal, never
 * per line.
 *
 * Rounding uses exact integer arithmetic (numerator / denominator), so the
 * result is correct for any input: no floating-point drift can push a .5
 * fraction the wrong way (e.g. 52.5 stays 52.5 instead of 52.4999...).
 */
function roundHalfUp(numerator, denominator) {
  const sign = numerator < 0 ? -1 : 1
  const abs = Math.abs(numerator)
  return sign * Math.floor((abs + denominator / 2) / denominator)
}

export function checkoutTotal(lines, couponRatePercent) {
  let discountedSubtotal = 0
  for (const line of lines) {
    const gross = line.unitPriceCents * line.qty
    const discount = line.qty >= 10 ? roundHalfUp(gross * 10, 100) : 0
    discountedSubtotal += gross - discount
  }
  const couponDiscount =
    couponRatePercent === null ? 0 : roundHalfUp(discountedSubtotal * couponRatePercent, 100)
  const amountAfterCoupon = discountedSubtotal - couponDiscount
  const tax = roundHalfUp(amountAfterCoupon * 8, 100)
  return { discountedSubtotal, couponDiscount, tax, total: amountAfterCoupon + tax }
}

args.command:
node --input-type=module -e "
import { checkoutTotal } from './src/checkout.js'
// Exact BigInt reference (half-away-from-zero on num/den).
const hup = (n, d) => { const s = n < 0n ? -1n : 1n; const a = n < 0n ? -n : n; return s * ((a + d/2n) / d) }
const ref = (lines, c) => {
  let ds = 0n
  for (const l of lines) { const g = BigInt(l.unitPriceCents) * BigInt(l.qty); const d = l.qty >= 10 ? hup(g*10n, 100n) : 0n; ds += g - d }
  const cd = c === null ? 0n : hup(ds * BigInt(c), 100n)
  const ac = ds - cd
  const tx = hup(ac*8n, 100n)
  return { discountedSubtotal: ds, couponDiscount: cd, tax: tx, total: ac + tx }
}
const same = (a, b) => a.discountedSubtotal === b.discountedSubtotal && a.couponDiscount === b.couponDiscount && a.tax === b.tax && a.total === b.total
let fails = 0
for (let i = 0; i < 200000; i++) {
  const n = 1 + Math.floor(Math.random()*6)
  const lines = Array.from({length: n}, () => ({ unitPriceCents: 1 + Math.floor(Math.random()*100000), qty: 1 + Math.floor(Math.random()*100) }))
  const c = Math.random() < 0.3 ? null : Math.floor(Math.random()*100)
  const r = checkoutTotal(lines, c), e = ref(lines, c)
  if (!same(r, e)) { fails++; if (fails <= 3) console.log('MISMATCH', JSON.stringify({lines, c, r, e})) }
}
console.log(fails === 0 ? 'ALL 200000 RANDOM CASES MATCH BigInt reference' : fails + ' mismatches')
// specific edge checks
console.log(JSON.stringify(checkoutTotal([{ unitPriceCents: 25, qty: 11 }], null)))   // 27.5 -> 28
console.log(JSON.stringify(checkoutTotal([{ unitPriceCents: 750, qty: 1 }], 7)))       // coupon 52.5 -> 53
console.log(JSON.stringify(checkoutTotal([], null)))                                   // empty cart
console.log(JSON.stringify(checkoutTotal([{ unitPriceCents: 3, qty: 1 }], 17)))        // tiny: 3*17/100 = 0.51 -> 1
console.log(JSON.stringify(checkoutTotal([{ unitPriceCents: 1, qty: 1 }], 50)))        // 1*50/100 = 0.5 -> 1
"

